package file

import (
	"context"
	"fmt"

	"github.com/Subject-Void-LLC/the-pleiades/pkg/capability"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/collection"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/inventory"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/remotefile"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/sdk"
)

// This file implements "file.symlink", generated by
// pleiades forge new-collection and then hand-completed.
//
// The whole method is one read of the path followed by one of four
// answers: it is already the link we want, it is a link pointing
// elsewhere, there is nothing there, or there is something there that is
// not a link at all. Reading first is not politeness. `ln -sfn` succeeds
// against a link that already points at the target, so an implementation
// that simply always ran it would be right about the device and wrong
// about the report, and a task that says changed on every run is a task
// whose report nobody can use to tell a real drift from a quiet one.
//
// Parameter names are Ansible's, from ansible.builtin.file with
// state=link: src is what the link points AT, path is the link itself,
// and dest is path's alias there. A person converting a playbook should
// be renaming nothing.

// Parameter names this method reads.
//
// They carry a symlink prefix for a reason that is about this package
// rather than about this method: package file holds one file per method,
// several of those methods need a parameter called path, and Go has one
// namespace for the whole package. An unprefixed paramPath here would
// collide with the identical constant file.remove and file.touch each
// need. The right end state is a single shared file for the names the
// whole namespace agrees on, which is one change made across all of the
// methods at once rather than claimed by whichever one lands first.
const (
	// symlinkParamSrc is the path the link points AT. Ansible's file
	// module calls it src when state is link, and it means the same here.
	symlinkParamSrc = "src"

	// symlinkParamPath is the link itself, the thing this method creates.
	symlinkParamPath = "path"

	// symlinkParamDest is Ansible's own alias for path, accepted for the
	// same reason the other names are Ansible's: a playbook that wrote
	// dest should land unchanged.
	symlinkParamDest = "dest"
)

func init() {
	collection.MustRegister(collection.Descriptor{
		Name: "file.symlink",
		Manifest: collection.Manifest{
			SupportedTransports: []string{
				"ssh",
			},
			RequiredCapabilities: []capability.Name{
				capability.NamePOSIXFileSystem,
			},
			ExecutionContext: collection.ExecutionContext{
				// Writing a link into /etc or /opt usually does need root,
				// but writing one into a home directory does not, and this
				// flag is a blanket claim rather than a per-path one.
				// Declaring it true would make every use of this method
				// demand elevation it may not need; the device refusing the
				// ln is the accurate answer for the cases that do.
				RequiresElevation: false,
			},
			PlatformTargets: nil,
			EngineVersion:   ">=0.2.0",
			Status:          collection.StatusImplemented,
			// It reads the path before it links, so a check can predict
			// through the same code (CheckSymlink).
			SupportsCheck: true,
			// Which inverse this is depends on what the run found, so the
			// run emits it and this field answers only whether one can
			// exist. See symlinkRecordInverse, and permRecordInverse for
			// the reasoning behind the split in full.
			Reversibility: collection.Reversibility{
				Reversible: true,
				Notes: "A run that created the link emits a file.remove naming it, which deletes the link and never what it " +
					"points at. A run that found a link already there and repointed it emits a file.symlink pointing back at " +
					"the target it had, because removing that link would delete something the run never created. A converged " +
					"run emits nothing, since it sent no command at all.",
				Inverses: []sdk.InverseSpec{
					{FQCN: "file.remove", Record: []string{"path"}},
					{FQCN: "file.symlink", Record: []string{"path"}, Withhold: []string{"src"}},
				},
			},
			Doc: symlinkDoc(),
		},
		Invoke: Symlink,
		Check:  CheckSymlink,
	})
}

// symlinkDoc is this method's reference documentation, kept out of the
// registration above so the manifest's own fields stay readable.
func symlinkDoc() collection.Doc {
	return collection.Doc{
		Summary:     "Makes a path a symbolic link pointing at a target, and refuses to replace a real file or directory.",
		Description: "Makes path be a symbolic link pointing at src, which is ansible.builtin.file with state=link. It reads the path before it acts and only sends a command when the answer differs, so a run that finds the link already pointing at src reports no change and sends no ln at all. A link pointing somewhere else is repointed. A path with nothing at it gets a new link. Anything else already there, a regular file, a directory, a socket, is refused rather than replaced, because ln would delete it and this method could not put it back; Ansible's force parameter is deliberately not implemented for that reason. src does not have to exist, which is ln's own behavior: a link to a path that is not there yet is a dangling link, and creating one is a real change like any other.",
		Params: []collection.Param{
			{Name: symlinkParamSrc, Type: "string", Required: true, Description: "The path the link points AT, written into the link exactly as given. It does not have to exist. A relative value is stored verbatim and is resolved by the system against the directory holding the link, not against the directory this task runs in."},
			{Name: symlinkParamPath, Type: "string", Required: true, Description: "The link itself, the path this task creates or repoints. Its parent directory must already exist: this method creates a link, never the directories above it. Ansible's alias dest is accepted for this too."},
			{Name: symlinkParamDest, Type: "string", Description: "Ansible's own alias for path, accepted so a converted playbook needs no renaming. Setting both of them to different paths is refused rather than guessed at."},
			{Name: sdk.ParamInsecureSkipHostKeyVerify, Type: "bool", Default: "false", Description: "Skip SSH host key verification for this task. This removes protection against a machine in the middle answering for the device, so set it only for a target you have decided does not need it."},
		},
		Returns: []collection.ReturnField{
			{Name: sdk.StatDiff, Type: "dict", Returned: "always", Description: "The path's state before and after, each carrying exists and kind, plus target when it is a link. It is recorded even on a run that changed nothing, because 'it was already like this' is exactly what tells a rollback to do nothing."},
		},
		Examples: []collection.Example{
			{
				Name:        "Point a stable name at a versioned release",
				RunbookYAML: "- name: Point current at the new release\n  file.symlink:\n    src: /opt/app/releases/1.4.2\n    path: /opt/app/current\n",
			},
			{
				Name:        "Repoint a link that already exists",
				RunbookYAML: "- name: Select the staging configuration\n  file.symlink:\n    src: /etc/app/config.staging.yaml\n    path: /etc/app/config.yaml\n",
			},
			{
				Name:        "Use dest, the way a converted playbook writes it",
				RunbookYAML: "- name: Link the vendor binary onto the path\n  file.symlink:\n    src: /opt/vendor/bin/tool\n    dest: /usr/local/bin/tool\n",
			},
		},
		SeeAlso: []string{"file.copy", "file.remove"},
	}
}

// Symlink implements the "file.symlink" collection method: it makes the
// path a symbolic link pointing at src, and leaves it alone when it
// already is one.
//
// # What Changed means here
//
// True only when a link was actually created or repointed. The converged
// case returns before any ln is built, so the device sees exactly the one
// stat probe and nothing else. That is the property worth protecting: it
// is what lets a runbook run on a schedule and have "changed" mean
// something moved.
//
// # Why a real file is refused instead of replaced
//
// `ln -sfn` would happily unlink a regular file or, with the wrong flags,
// write inside a directory. Replacing a directory with a link destroys
// whatever was under it, and nothing in this platform can put it back:
// there is no journal yet, and even with one the content was never read.
// Ansible offers force for this and this method deliberately does not,
// because the failure mode of a wrong path in a variable is unbounded and
// the cost of refusing is one clear error. A task that really means to
// replace a real file names file.remove first, where the destruction is
// visible in the runbook.
//
// # The read-back after the write
//
// The after half of the diff comes from a second stat rather than from
// what this method believes it just did. It costs one round trip and it
// buys the difference between reporting the device's state and reporting
// our own intent, which are the same thing right up until the moment they
// are not.
func Symlink(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	return symlink(ctx, rc, device, params, collection.ModeExecute)
}

// CheckSymlink is file.symlink's check: the same read and the same
// refusal as Symlink, through the one body both share, then a prediction
// instead of the link. A link already pointing at src predicts no change;
// anything else predicts one, with a diff whose After half is
// remotefile.PredictSymlink.
func CheckSymlink(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	return symlink(ctx, rc, device, params, collection.ModeCheck)
}

// symlink is Symlink's and CheckSymlink's one body; mode says which.
func symlink(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any, mode collection.Mode) (collection.Result, error) {
	const fqcn = "file.symlink"

	// Both parameters are read before connecting, so a runbook mistake
	// costs no round trip and the error names the runbook rather than the
	// device.
	src, err := sdk.RequiredStringParam(params, symlinkParamSrc)
	if err != nil {
		return collection.Result{}, fmt.Errorf("%s: %w: name the path the link should point at", fqcn, err)
	}
	linkPath, err := symlinkLinkPath(params)
	if err != nil {
		return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
	}

	conn, err := sdk.Connect(ctx, rc, device, params, fqcn)
	if err != nil {
		return collection.Result{}, err
	}
	defer func() { _ = conn.Close() }()

	// Read before acting. Everything below is a decision about what this
	// one answer said.
	before, err := remotefile.Stat(ctx, conn, linkPath)
	if err != nil {
		return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
	}

	// Stat reports a link as a link even when it points at a directory,
	// which is what makes this single check enough: anything that exists
	// and is not a link is real content this method will not destroy.
	if before.Exists() && before.Kind != remotefile.KindSymlink {
		return collection.Result{}, fmt.Errorf(
			"%s: %s is a %s, not a symbolic link: refusing to replace it, because ln would delete it and nothing here could put it back",
			fqcn, linkPath, before.Kind)
	}

	// The one case that must send nothing at all. Both halves matter: a
	// link to the wrong place is a change, and so is no link at all.
	converged := before.Kind == remotefile.KindSymlink && before.Target == src

	if mode == collection.ModeCheck {
		predicted := before.Map()
		if !converged {
			predicted = remotefile.PredictSymlink(src).Map()
		}
		if err := sdk.RecordDiff(rc, sdk.Diff{Before: before.Map(), After: predicted}); err != nil {
			return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
		}
		return collection.Result{Changed: !converged}, nil
	}

	after := before
	if !converged {
		// remotefile.Symlink passes -n, and that flag is load-bearing
		// rather than tidy. Without it, `ln -sf target link` where link is
		// an existing symlink to a DIRECTORY follows the link and creates
		// the new one INSIDE that directory, so the task reports success
		// while the link it was asked to repoint still points exactly
		// where it did. With -n the existing link is treated as the thing
		// being replaced, which is what this method promised.
		if err := remotefile.Symlink(ctx, conn, src, linkPath); err != nil {
			return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
		}
		if after, err = remotefile.Stat(ctx, conn, linkPath); err != nil {
			return collection.Result{}, fmt.Errorf("%s: reading %s back after linking it: %w", fqcn, linkPath, err)
		}
	}

	// Recorded on every path, including the converged one, where the two
	// halves are equal. An absent diff cannot express "this task made no
	// change, so undoing it means doing nothing", and that is precisely
	// what a rollback reading a journal has to be able to tell apart from
	// "this task was never recorded".
	if err := sdk.RecordDiff(rc, sdk.Diff{Before: before.Map(), After: after.Map()}); err != nil {
		return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
	}
	// The converged run emits no inverse, which is the same statement the
	// matching diff halves make: this task changed nothing, so undoing it
	// means doing nothing.
	if !converged {
		if err := symlinkRecordInverse(rc, fqcn, linkPath, before); err != nil {
			return collection.Result{}, fmt.Errorf("%s: %w", fqcn, err)
		}
	}

	return collection.Result{Changed: !converged}, nil
}

// symlinkRecordInverse writes the instruction that undoes this run, which
// is one of two entirely different instructions depending on whether there
// was a link there already.
//
// Removing the link is the inverse ONLY when this run created it. When the
// path was already a link and this run repointed it, the link is not this
// run's to delete: it existed before, something else made it, and the only
// thing this run changed was where it pointed. So the inverse there points
// it back, which is the same method again with the old target. That is
// rule two of the contract, the same one that stops file.directory
// deleting a directory it merely chmodded. See permRecordInverse for the
// reasoning in full.
//
// The two cases below are exhaustive because Symlink already refused
// everything else: by the time this is reached the path is either absent
// or a symbolic link, never a file or a directory.
func symlinkRecordInverse(rc sdk.RunbookContext, fqcn, linkPath string, before remotefile.Info) error {
	if !before.Exists() {
		// file.remove's own parameter name, which is why it is written out
		// rather than reusing this file's constants.
		return sdk.RecordInverse(rc, sdk.Inverse{
			FQCN:   "file.remove",
			Params: map[string]any{"path": linkPath},
			Description: fmt.Sprintf("Remove the symbolic link %s, which this task created. What it points at is left alone, "+
				"since file.remove deletes a link as the link.", linkPath),
		})
	}
	return sdk.RecordInverse(rc, sdk.Inverse{
		FQCN: fqcn,
		Params: map[string]any{
			symlinkParamSrc:  before.Target,
			symlinkParamPath: linkPath,
		},
		Description: fmt.Sprintf("Point %s back at %s, where it pointed before this task repointed it. The link is not "+
			"removed, because this task did not create it.", linkPath, before.Target),
	})
}

// symlinkLinkPath reads the link's own path from either of the two names
// Ansible accepts for it, and refuses a task that sets both to different
// values.
//
// Ansible's file module makes dest an alias of path, so a converted
// playbook may say either one. Guessing when the two disagree is the case
// worth refusing rather than resolving: they name two different paths, so
// whichever this method dropped would leave a link somewhere the author
// never asked about while the path they were actually reading in the
// runbook stayed untouched. That failure is silent, and it is silent in
// the direction of having changed the wrong thing.
func symlinkLinkPath(params map[string]any) (string, error) {
	path := sdk.StringParam(params, symlinkParamPath)
	dest := sdk.StringParam(params, symlinkParamDest)

	switch {
	case path != "" && dest != "" && path != dest:
		return "", fmt.Errorf("%s is %q and %s is %q, but they are the same parameter: set one of them",
			symlinkParamPath, path, symlinkParamDest, dest)
	case path != "":
		return path, nil
	case dest != "":
		return dest, nil
	default:
		return "", fmt.Errorf("%s is required: name the link this task should create", symlinkParamPath)
	}
}
